% aa_demo_ROS_based_synthesizer_runPLL.m -- center design, fixed-filter band sweep.
% Generated by GitHub Copilot under Lance Lascari's direction.
% GNU Octave first; MATLAB compatible. Run by script name from this folder,
% or let ../demo_2026.m call it after the ROS data presentation.
% Settings follow aa_RunPllDesign_XXXX.m's grouping and parameter order.
% No clc/close-all/clear: retain the displayed source evidence and ROS plots.
%
% The Mathcad worksheet's charge-pump filter synthesis and PFD phase-delay
% compensation remain in the existing core. The new step is to synthesize
% once at the band center, freeze C1/C2/R2/C3/R3, then select ROS noise/Kvco
% at each analysis frequency. This is NOT a bandwidth-target redesign sweep.

demo_pll_directory=fileparts(mfilename('fullpath'));
addpath(demo_pll_directory,fullfile(demo_pll_directory,'..','pn'));
% Root demo passes its generated profile. Standalone use regenerates it from
% shipped numeric rows; there is no dependency on ~/Downloads or local MATs.
if ~exist('demo_ros_profile_s','var')
    ros_example_options_s=struct();
    ros_example_options_s.bSaveData=0;
    ros_example_options_s.bPlotData=0;
    aa_generate_ros2100_example;
    clear ros_example_options_s;
    demo_ros_profile_s=pn_profile_s;
end
validate_pn_profile(demo_ros_profile_s);
if ~exist('demo_output_directory','var')
    demo_output_directory=fullfile(demo_pll_directory,'_demo_2026');
end
if ~exist('demo_overwrite_results','var')
    demo_overwrite_results=1;
end
if exist(demo_output_directory,'dir')~=7
    [ok,message]=mkdir(demo_output_directory);
    if ~ok
        error('Cannot create demo results directory: %s',message);
    end
end

% System: bare VCO output; center frequency (Hz) is the specified band midpoint.
pll_inputs_s.fout_desired_Hz=1725e6;
pll_inputs_s.mult=1; % final output / VCO frequency; keep 1 for this ROS band
pll_inputs_s.Fref_Hz=100e3; % PFD comparison frequency, not the reference carrier
pll_inputs_s.Kvco_Hz_volt=20e6; % manual fallback; profile-selected Kvco overrides it
pll_inputs_s.Kphi_A_cycle=1e-3; % default 1 mA charge-pump / phase-detector gain
pll_inputs_s.BW_desired_Hz=5e3; % center-design bandwidth target (Hz), not every case's achieved BW
pll_inputs_s.PM_desired_deg=55; % default center-design phase-margin target (degrees)
pll_inputs_s.ATTEN_dB=0.01; % default additional third-pole attenuation at the PFD frequency

% Reference and PLL noise: default chip/reference assumptions, not extracted
% from the ROS standalone VCO datasheet. No local reference measurement needed.
pll_inputs_s.bUseTCXOFromFile=0;
pll_inputs_s.F_tcxo_Hz=16e6; % nominal reference oscillator frequency (Hz)
pll_inputs_s.FileTCXO='../pn/datfiles_local/16M_VCTCXO_20250930a_pndata.mat'; % unused
pll_inputs_s.Ntcxo_ref_dBc=-135; % default reference SSB noise anchor (dBc/Hz)
pll_inputs_s.Ftcxo_ref_offset_Hz=100; % offset of that reference anchor (Hz)

pll_inputs_s.bUseVCOFromFile=1; % profile option below exports a scalar source for each case
pll_inputs_s.FileVCO='ROS_2100_119_profile.mat'; % placeholder; opt-in profile supplies the data
pll_inputs_s.Nvco_ref_dBc=-115; % unused manual VCO anchor in profile mode
pll_inputs_s.Fvco_ref_offset_Hz=10e3; % unused manual VCO anchor offset (Hz)
pll_inputs_s.Npd_ref_dBc=-201; % default phase-detector noise figure of merit (dBc/Hz)

pll_inputs_s.def_filename='_ROS_based_synthesizer.mat'; % viewer dataset and case-export basename
% Keep the original analysis grid. ROS evidence spans 1 kHz-1 MHz only;
% the historical core holds endpoint noise outside that range (prints a note).
% Those extensions are modeling assumptions, not additional datasheet values.
pll_inputs_s.fstart_main_Hz=10; % minimum analysis offset (Hz)
pll_inputs_s.fstop_main_Hz=200e6; % maximum analysis offset (Hz)
pll_inputs_s.fsweep_main_pts=401; % log grid points; measured crossover resolution

% Center design: synthesize ALL components, with no manual/third-pole override.
pll_inputs_s.filter_override=0;
pll_inputs_s.filter_override_3rdpole_only=0;
pll_inputs_s.CC1=1e-12; % F; replaced by the center design before the sweep
pll_inputs_s.CC2=1e-12; % F; R2/C2 shunt branch
pll_inputs_s.RR2=1; % ohm; R2/C2 shunt branch
pll_inputs_s.CC3=1e-12; % F; tuning-node capacitor
pll_inputs_s.RR3=1; % ohm; series resistor to tuning node

% Outputs and transients: normal defaults from the existing example.
% Hide per-case core windows below; the aggregate viewer still opens.
pll_inputs_s.bSaveFigs=1; % file-only exports; 0 speeds up exploratory reruns
pll_inputs_s.bSaveFigsPDF=0;
pll_inputs_s.bSaveFigsJPG=1; % per-case figures under the demo case directory
pll_inputs_s.bDoTransient=1; % small-signal settling estimate
pll_inputs_s.transient_delta_f_Hz=500e3; % shared initial frequency error (Hz)
pll_inputs_s.transient_tmax_s=15e-3; % duration (s); extend for not-settled cases
pll_inputs_s.transient_points=12501; % small-signal samples
pll_inputs_s.transient_ftol_Hz=1e3; % settling tolerance (+/- Hz)
pll_inputs_s.bDoTransientNonlinear=1; % nonlinear PFD/charge-pump acquisition estimate
pll_inputs_s.transient_nl_steps_per_ref=100; % steps per PFD period; reduce for a faster demonstration
pll_inputs_s.transient_nl_fvco_min_Hz=-Inf; % no modeled hard tuning limit
pll_inputs_s.transient_nl_fvco_max_Hz=Inf;
pll_inputs_s.pn_ylimits=[-200 0]; % plot-only SSB noise range (dBc/Hz)
pll_inputs_s.bWriteCSVtable=1; % per-case settings/components/noise table

% Analyze the specified band, not the wider typical characterization range.
% Tweak this explicit list to change the carrier points (Hz).
run_options_s=struct();
run_options_s.bRunSweep=1;
run_options_s.sweep_parameter='fout_desired_Hz';
run_options_s.sweep_values=[1350e6 1537.5e6 1725e6 1912.5e6 2100e6];
run_options_s.integration_lower_Hz=100; % offset Hz; historical endpoint extension below 1 kHz
run_options_s.integration_upper_Hz=1e6; % offset Hz; same limits for all cases
run_options_s.noise_offsets_Hz=[100 1000 10000 100000]; % summary comparison offsets (Hz)
run_options_s.bShowCorePlots=0; % avoid five sets of analysis windows; retain file exports
run_options_s.bEnableDataViewer=1; % existing reloadable aggregate/noise/transient viewer
run_options_s.bOverwriteResults=demo_overwrite_results; % demo reruns overwrite only their own outputs
run_options_s.base_directory=demo_output_directory;
% Opt-in programmatic profile input; old file-only callers remain unchanged.
% Carrier selection is at fout_desired_Hz/mult, with explicit modeled
% interpolation between characterized points and no carrier extrapolation.
run_options_s.vco_profile_s=demo_ros_profile_s;

fprintf('\nCenter design: %.1f MHz, %.0f Hz loop BW, %.0f degree target PM.\n', ...
    pll_inputs_s.fout_desired_Hz/1e6,pll_inputs_s.BW_desired_Hz,pll_inputs_s.PM_desired_deg);
% The center pass only needs frequency-domain synthesis. Do not export its
% temporary plots or run transients before freezing the filter.
center_inputs_s=pll_inputs_s;
center_inputs_s.def_filename='_ROS_center_design.mat';
center_inputs_s.bSaveFigs=0;
center_inputs_s.bWriteCSVtable=0;
center_inputs_s.bDoTransient=0;
center_inputs_s.bDoTransientNonlinear=0;
center_options_s=run_options_s;
center_options_s.bRunSweep=0;
center_options_s.bShowCorePlots=0;
center_options_s.bEnableDataViewer=0;
ROS_CENTER_DATA_s=rfdude_pll_run(center_inputs_s,center_options_s);
center_case_s=ROS_CENTER_DATA_s.cases{1};
if ~ROS_CENTER_DATA_s.completed(1)
    error('ROS center design failed; do not run a sweep with an undefined filter.');
end

% Show and freeze the actual calculated values, rather than rounded guesses.
% All five cases use these exact components; achieved BW/PM are allowed to vary.
pll_inputs_s.filter_override=1;
pll_inputs_s.CC1=center_case_s.components.C1;
pll_inputs_s.CC2=center_case_s.components.C2;
pll_inputs_s.RR2=center_case_s.components.R2;
pll_inputs_s.CC3=center_case_s.components.C3;
pll_inputs_s.RR3=center_case_s.components.R3;
fprintf('Center achieved BW %.6g Hz, PM %.6g deg; selected Kvco %.6g MHz/V.\n', ...
    center_case_s.BW_actual_Hz,center_case_s.PM_actual_deg,center_case_s.Kvco_Hz_volt/1e6);
fprintf('Fixed filter: C1=%.12g F, C2=%.12g F, R2=%.12g ohm, C3=%.12g F, R3=%.12g ohm.\n', ...
    pll_inputs_s.CC1,pll_inputs_s.CC2,pll_inputs_s.RR2,pll_inputs_s.CC3,pll_inputs_s.RR3);
fprintf('Sweep: 1350, 1537.5, 1725, 1912.5 and 2100 MHz with that same filter.\n');
fprintf('ROS noise and Kvco change per carrier; the 5 kHz target is NOT redesigned per case.\n');
% Embed the center-design evidence in the saved sweep config for later review.
run_options_s.center_design_s=struct('inputs',center_inputs_s, ...
    'components',center_case_s.components,'BW_actual_Hz',center_case_s.BW_actual_Hz, ...
    'PM_actual_deg',center_case_s.PM_actual_deg,'Kvco_Hz_volt',center_case_s.Kvco_Hz_volt);
PLL_DATA_s=rfdude_pll_run(pll_inputs_s,run_options_s);
if ~all(PLL_DATA_s.completed)
    error('ROS demonstration has failed cases; inspect the checkpointed dataset.');
end
fprintf('Demo complete. Use the viewer to compare noise, achieved BW/PM and transients.\n');
fprintf('Reopen without rerunning: cc_pll_data_viewer(''%s'')\n',PLL_DATA_s.dataset_path);
